import { JobQueue, type Job } from "./queue.js";

export async function runOnce(queue: JobQueue, handle: (job: Job) => Promise<void>): Promise<boolean> {
  const job = queue.next();
  if (!job) return false;
  try {
    await handle(job);
  } catch {
    queue.requeue(job);
  }
  return true;
}

