const MAX_BACKOFF_MS = 20_000;

export function retryDelay(attempt: number): number {
  return Math.min(MAX_BACKOFF_MS, 250 * 2 ** attempt);
}

export function shouldRetry(attempt: number): boolean {
  return attempt < 5;
}

